{
  "apiVersion": "platform/v1",
  "kind": "PipelineConfig",
  "build": {
    "agent": "go-1.23",
    "platforms": [
      "arm64"
    ],
    "unitTest": {
      "enabled": false,
      "command": "./test.sh"
    },
    "containerfile": "./Containerfile",
    "artifacts": [],
    "sonar": false,
    "cache": {
      "enabled": false,
      "size": "small"
    },
    "sourceVolume": {
      "size": "small"
    }
  },
  "pipelines": {
    "ci": {
      "trigger": {
        "source": "git",
        "event": "push",
        "branch": "main"
      },
      "steps": [
        {
          "stage": "build"
        },
        {
          "stage": "deploy",
          "env": "dev"
        }
      ]
    }
  },
  "deploy": {
    "target": "aws-ecs",
    "ecs": {
      "cluster": "glidepath-smoke",
      "service": "glidepath-smoke",
      "containerName": "app",
      "region": "us-east-1",
      "taskDefinitionFamily": "glidepath-smoke"
    },
    "lowerEnvironments": [
      "dev"
    ],
    "upperEnvironments": [],
    "strategy": "rollout",
    "promotionOrder": [
      "dev"
    ],
    "releaseFile": "glidepath/releases/{env}.yaml",
    "lambda": {
      "region": "us-east-1"
    },
    "azureContainerApps": {}
  },
  "secrets": [
    {
      "name": "aws-access-key-id"
    },
    {
      "name": "aws-secret-access-key"
    }
  ],
  "test": {
    "enabled": true
  },
  "ephemeralEnvironments": {
    "branch": {
      "enabled": false,
      "patterns": [
        "preview/*"
      ]
    },
    "pullRequest": {
      "enabled": false,
      "labels": [
        "preview"
      ]
    },
    "ttl": "5d"
  },
  "governance": {
    "sast": false,
    "imageScan": false,
    "policyCheck": false,
    "sbom": false,
    "allowedCommitSigners": []
  },
  "notifications": {
    "slack": {
      "enabled": false,
      "scanResults": true
    },
    "backstage": {
      "enabled": false
    }
  }
}

